UPDATE orders
SET status = #{status}
WHERE order_id = #{orderId}

mapper.select:
SELECT p.id AS paymentId, p.user_name AS clientName, p.payment_price AS price, p.payment_fee AS platformFee, (p.payment_price - p.payment_fee) AS netAmount, p.status AS status, p.method AS method, DATE_FORMAT(p.payment_date, '%Y-%m-%d') AS paymentDate, DATE_FORMAT(p.payment_date, '%H:%i') AS paymentTime FROM PAYMENT p WHERE p.trainer_id = #{trainerId} AND p.payment_type = 'PT' ORDER BY
p.user_name p.payment_price (p.payment_price - p.payment_fee) p.status p.payment_date
${sortDir} LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM PAYMENT p
WHERE p.trainer_id = #{trainerId}
  AND p.payment_type = 'PT'
